-- step66: PageSpeed — старые стили (6 блокирующих файлов, ~41 КБ gzip) на страницах нового дизайна заменены одним legacy.css (подключает lb-head);
-- полные старые файлы остаются у «Категория NEW» (19) и «Обучение» (15). Повторный запуск безопасен.
SET NAMES utf8mb4;

-- чанк head (шапка <head> старых и новых шаблонов): 6 старых файлов — только для шаблона 19
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(snippet, '    <link rel=\"stylesheet\" href=\"/assets/templates/css/reset.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/reset.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/template.css?ver=1.0.2\"/>\n	<link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/template.css?ver=1.0.2\"/>\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/blog.css?ver=17.02.2403\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/blog.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/fonts.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/fonts.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/media.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/media.css\"/> -->\n    \n    <link rel=\"stylesheet\" href=\"/assets/templates/css/slimmenu.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/slimmenu.css\"/> -->', '    {* старые стили — только «Категория NEW» (19, старые блоки); на страницах нового дизайна — legacy.css из lb-head (шаг 66) *}\n    {if $_modx->resource.template == 19}\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/reset.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/reset.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/template.css?ver=1.0.2\"/>\n	<link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/template.css?ver=1.0.2\"/>\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/blog.css?ver=17.02.2403\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/blog.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/fonts.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/fonts.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/media.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/media.css\"/> -->\n    \n    <link rel=\"stylesheet\" href=\"/assets/templates/css/slimmenu.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/slimmenu.css\"/> -->\n    {/if}') WHERE name = 'head' AND snippet NOT LIKE '%resource.template == 19%';
-- шаблоны «404 eror page» и «Success-Page-RU» (свой <head>): 6 старых файлов убраны — legacy.css даёт lb-head
UPDATE Impulse_Digital_X_site_templates SET content = REPLACE(content, '    <link rel=\"stylesheet\" href=\"/assets/templates/css/reset.css\" />\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/template.css?ver=1.0.2\"/>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/blog.css?ver=17.02.2403\"/>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/fonts.css\"/>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/media.css\"/>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/slimmenu.css\"/>\n', '') WHERE templatename = '404 eror page';
UPDATE Impulse_Digital_X_site_templates SET content = REPLACE(content, '    <link rel=\"stylesheet\" href=\"/assets/templates/css/reset.css\" />\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/template.css?ver=1.0.2\"/>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/blog.css?ver=17.02.2403\"/>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/fonts.css\"/>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/media.css\"/>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/slimmenu.css\"/>\n', '') WHERE templatename = 'Success-Page-RU';
-- чанк head-blog-list (<head> списка статей): то же
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(snippet, '    <link rel=\"stylesheet\" href=\"/assets/templates/css/reset.css\" />\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/template.css?ver=19.08.2315\" />\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/blog.css?ver=17.02.2403\" />\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/fonts.css\" />\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/media.css\" />\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/slimmenu.css\" />\n', '') WHERE name = 'head-blog-list';
